dslRule:
private final $Type $name = $init; :: isField($name) && !isStatic($name) && hasNoSideEffect($init)
=> private static final $Type $name = $init;
;;

beforeExample:
public class Example {
    public static class Inner {
        private final String SETTINGS_ID = "com.example.plugin" + ".DIALOG";
        private final int MAX_VALUE = 100;
    }
}

afterExample:
public class Example {
    public static class Inner {
        private static final String SETTINGS_ID = "com.example.plugin" + ".DIALOG";
        private static final int MAX_VALUE = 100;
    }
}

negativeExample:
public class Example {
    public static class Inner {
        private final String INSTANCE_ID = java.util.UUID.randomUUID().toString(); // Initializer has side effect, should not match
        private static final String ALREADY_STATIC = "constant"; // Already static, should not match
        public final String PUBLIC_CONSTANT = "value"; // Not private, should not match
    }
}
